// <form-view> — the form surface. THE reinvention: a form IS its schema. The form
// owns one declarative schema (inline JSON `schema` attr/property, OR built from
// its child <form-field> rules), runs `src/validate` against the live values on
// input + on submit, blocks submit while invalid, and writes errors back down to
// each field — validation is never hand-wired per control. Themed entirely from
// --work-* tokens.
//
// Events:
//   work-submit  { detail: { values } }  — fired only when the record is valid
//   work-invalid { detail: { errors } }  — fired when a submit is blocked
//   work-change  { detail: { values, valid } } — on every field input (live)
//
// Standalone (sync floor) by default; when a Host with a /validate route is
// reachable (this.host.available("validate")) it merges server/derived errors
// on submit via validateRecordAsync — the floor stays authoritative for what it
// can decide, the Host only adds what it alone knows (uniqueness, cross-record).
//
// Usage:
//   <form-view>
//     <form-field name="email" type="email" label="Email" required></form-field>
//     <form-field name="pw" type="password" label="Password" required min="8"></form-field>
//     <wb-button type="submit" slot="actions">Create</wb-button>
//   </form-view>
import { WbElement, html, css, define } from "../../core/element.js";
import { validateRecord, validateRecordAsync, parseSchema } from "../../validate/index.js";

export class WbForm extends WbElement {
  static props = ["schema", "submit-label", "novalidate", "live"];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    form { display: block; }
    .fields { display: block; }
    .actions { display: flex; gap: var(--work-space-3); align-items: center; margin-top: var(--work-space-4); }
    .summary { margin: 0 0 var(--work-space-4); padding: var(--work-space-3) var(--work-space-4);
      border-radius: var(--work-radius); background: var(--work-err-faint);
      border: 1px solid var(--work-err); color: var(--work-err); font-size: var(--work-text-sm);
      font-weight: 500; line-height: 1.5; display: none; }
    :host([invalid]) .summary[data-has] { display: block; }
    .submit { font: 600 var(--work-text) var(--work-font); padding: var(--work-space-3) var(--work-space-5);
      border-radius: var(--work-radius); border: 1.5px solid transparent;
      background: var(--work-brand); color: var(--work-on-brand); cursor: pointer;
      transition: transform var(--work-dur) var(--work-ease), box-shadow var(--work-dur) var(--work-ease); }
    .submit:hover { transform: translateY(-1px); }
    .submit:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    .submit[disabled] { opacity: 0.5; pointer-events: none; }
  `;

  /** The form's schema — explicit property/attr wins; otherwise built from the
   *  child <form-field> rules (the form IS its schema). */
  get schema() {
    if (this._schema) return this._schema;
    const attr = this.attr("schema");
    if (attr) { try { return parseSchema(JSON.parse(attr)); } catch { /* fall through */ } }
    return this._schemaFromFields();
  }
  set schema(v) { this._schema = v; }

  _fields() {
    return Array.from(this.querySelectorAll("form-field"));
  }

  _schemaFromFields() {
    const s = {};
    for (const f of this._fields()) {
      const name = f.getAttribute("name");
      if (name && f.rule) s[name] = f.rule;
    }
    return s;
  }

  /** The native <form> the fields actually participate in. A Form-Associated
   *  Custom Element associates with the nearest ANCESTOR <form> in its own tree —
   *  the <form-field>s live in this element's light DOM, so that is the <form>
   *  the author wraps <form-view> in (`<form><form-view>…`). The inner shadow
   *  <form> is layout/submit-affordance only and is NOT where slotted fields
   *  associate, so we read the owning light-DOM form for native participation. */
  get _ownerForm() {
    return this.closest("form");
  }

  /** The owning form's native FormData — the fields' submitted values (FACE).
   *  Proves native participation: each field appears here under its `name`
   *  because it called setFormValue, with NO manual DOM harvesting. Empty when
   *  <form-view> is not wrapped in a real <form> (standalone usage). */
  formData() {
    const form = this._ownerForm;
    return form && typeof FormData === "function" ? new FormData(form) : new FormData();
  }

  /** Current { name: typed-value } record for the schema floor. The validate
   *  layer needs TYPED values (number→number, checkbox→boolean) and the presence
   *  of empty fields to fire `required`; native FormData yields only strings and
   *  drops unchecked checkboxes, so the typed record is read from each field's
   *  `value` (the same value the field published to the form via setFormValue).
   *  `formData()` exposes the raw native submission separately. */
  get values() {
    const out = {};
    for (const f of this._fields()) {
      const name = f.getAttribute("name");
      if (name) out[name] = f.value;
    }
    return out;
  }

  render() {
    const label = this.attr("submit-label", "Submit");
    return html`
      <form novalidate @submit=${this._onSubmit}>
        <p class="summary" role="alert"></p>
        <div class="fields"><slot></slot></div>
        <div class="actions">
          <slot name="actions"><button class="submit" type="submit">${label}</button></slot>
        </div>
      </form>`;
  }

  connectedCallback() {
    super.connectedCallback();

    // Live validation: any field input bubbles work-field-input / work-field-blur.
    this.addEventListener("work-field-input", (e) => {
      this.dispatchEvent(new CustomEvent("work-change", {
        bubbles: true, composed: true,
        detail: { values: this.values, valid: validateRecord(this.values, this.schema).valid },
      }));
      // Re-validate just the touched field if it currently shows an error (clear-on-fix),
      // or always when `live` is set.
      const touched = e.detail && e.detail.name;
      if (this.boolAttr("live") || this._submitted || this._fieldInvalid(touched)) this._revalidateField(touched);
    });
    this.addEventListener("work-field-blur", (e) => {
      if (this._submitted || this.boolAttr("live")) this._revalidateField(e.detail && e.detail.name);
    });

    // A slotted action button might be a <wb-button> not a real submit; catch clicks.
    this.addEventListener("click", (e) => {
      const t = e.target;
      const tag = t && t.tagName && t.tagName.toLowerCase();
      if ((tag === "wb-button" || (t && t.getAttribute && t.getAttribute("type") === "submit")) &&
          (t.slot === "actions" || t.getAttribute("slot") === "actions")) {
        e.preventDefault(); this.submit();
      }
    });

    // Native form participation: when the author wraps <form-view> in a real
    // <form>, the child <form-field>s are Form-Associated to THAT form. Run the
    // schema floor on the owning form's native submit so the floor's errors flow
    // into each field's native validity (setValidity via setError) and the
    // browser blocks the submit on any invalid field — the floor and native
    // constraint validation are one path, not two. The work-submit/work-invalid
    // events fire exactly as before (via submit()).
    const owner = this._ownerForm;
    if (owner && !owner.__workFormBound) {
      owner.__workFormBound = true;
      owner.addEventListener("submit", (e) => {
        // submit() seeds field validity from the floor; if anything is invalid the
        // native submit must not proceed.
        this.submit();
        if (this._fields().some((f) => f.hasAttribute("invalid"))) e.preventDefault();
      });
    }
  }

  // Native submit from a slotted real <button type=submit> or the default.
  _onSubmit(e) { e.preventDefault(); this.submit(); }

  _fieldByName(name) {
    return this._fields().find((f) => f.getAttribute("name") === name);
  }
  _fieldInvalid(name) {
    const f = this._fieldByName(name);
    return f && f.hasAttribute("invalid");
  }

  /** Validate one field and write/clear its error (live path). */
  _revalidateField(name) {
    if (!name) return;
    const schema = this.schema;
    const rule = schema[name];
    if (!rule) return;
    const { errors } = validateRecord(this.values, { [name]: rule });
    const f = this._fieldByName(name);
    if (f) f.setError(errors.length ? errors[0].message : null);
    this._refreshSummary();
  }

  /** Apply a full error list down to the fields + the summary. */
  _applyErrors(errors) {
    const byField = {};
    for (const e of errors) { if (!byField[e.path]) byField[e.path] = e.message; }
    for (const f of this._fields()) {
      const name = f.getAttribute("name");
      f.setError(byField[name] || null);
    }
    if (errors.length) this.setAttribute("invalid", ""); else this.removeAttribute("invalid");
    this._refreshSummary(errors);
  }

  _refreshSummary(errors) {
    const sum = this.shadowRoot && this.shadowRoot.querySelector(".summary");
    if (!sum) return;
    const list = errors || this._fields()
      .filter((f) => f.hasAttribute("invalid"))
      .map((f) => ({ message: f.getAttribute("error") }));
    if (list.length) {
      sum.setAttribute("data-has", "");
      sum.textContent = list.length === 1
        ? list[0].message
        : `${list.length} fields need attention.`;
    } else {
      sum.removeAttribute("data-has");
      sum.textContent = "";
    }
  }

  /** Run validation; on valid → work-submit, on invalid → work-invalid + mark fields. */
  async submit() {
    this._submitted = true;
    const values = this.values;
    const schema = this.schema;
    if (this.boolAttr("novalidate")) {
      this.dispatchEvent(new CustomEvent("work-submit", { bubbles: true, composed: true, detail: { values } }));
      return { valid: true, values };
    }
    // Sync floor first (instant), then optional Host merge.
    let result = validateRecord(values, schema);
    this._applyErrors(result.errors);
    if (!result.valid) {
      this.dispatchEvent(new CustomEvent("work-invalid", { bubbles: true, composed: true, detail: { errors: result.errors } }));
      return result;
    }
    // Floor passed — consult the Host for server/derived errors when reachable.
    const merged = await validateRecordAsync(values, schema, this.host);
    if (!merged.valid) {
      this._applyErrors(merged.errors);
      this.dispatchEvent(new CustomEvent("work-invalid", { bubbles: true, composed: true, detail: { errors: merged.errors } }));
      return merged;
    }
    this.removeAttribute("invalid");
    this._refreshSummary([]);
    this.dispatchEvent(new CustomEvent("work-submit", { bubbles: true, composed: true, detail: { values } }));
    return { valid: true, values };
  }

  /** Programmatic validate without firing submit (useful for records/tables). */
  validate() {
    const r = validateRecord(this.values, this.schema);
    this._applyErrors(r.errors);
    return r;
  }

  reset() {
    this._submitted = false;
    for (const f of this._fields()) { f.value = ""; f.clearError(); }
    this.removeAttribute("invalid");
    this._refreshSummary([]);
  }
}

define("form-view", WbForm);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// workponents · validate — barrel for the shared validation layer.
//
// The cross-cutting Validation pillar (a form/record IS its schema; validation
// runs against a declarative rule contract, not hand-wired per field). Zero-dep,
// framework- and token-unaware pure logic. Consumed by `forms` now; `records` /
// `tables-edit` reuse the same contract + result shape later.
//
//   import { validate, validateRecord } from "../../validate/index.js";
//
// Contract & result shape are documented in ./rules.js (read that for the full
// rule grammar). The uniform result everywhere: { valid, errors:[{path,rule,message}] }.
export {
  validate,
  validateRecord,
  validateRecordAsync,
  serializeSchema,
  parseSchema,
} from "./rules.js";

// workponents · validate — the shared, declarative validation layer.
//
// The cross-cutting Validation pillar. Zero-dependency, framework- AND
// token-unaware (pure logic): no DOM, no CSS, no custom-element coupling. The
// `forms` surface consumes it now; `records` / `tables-edit` reuse the SAME
// contract + result shape later — so validation is authored once, as source,
// not hand-wired per field.
//
// ── The rule contract ──────────────────────────────────────────────────────
// A field rule is a plain object (declarative source — serializable to/from
// JSON, agent-editable). Recognized keys:
//
//   { type:     "string"|"number"|"integer"|"boolean"|"email"|"url"|"date",
//     required: true,                 // non-empty / present
//     min, max:  Number,              // number range, OR string/array length
//     minLength, maxLength: Number,   // explicit length (alias of min/max for strings)
//     pattern:  RegExp | string,      // string must match (string = RegExp source)
//     enum:     [..allowed values..], // value must be one of these
//     equals:   <ref>,                // cross-field: must equal sibling field <ref>
//     custom:   (value, ctx) => true | "message",  // arbitrary predicate
//     message:  "override message",   // single message for any failure on this field
//     label:    "Email address",      // human label used in default messages
//   }
//
// A SCHEMA maps field path → rule:  { email: {type:"email", required:true}, ... }
//
// ── The result shape (uniform, every surface returns this) ──────────────────
//   { valid: Boolean, errors: [ { path, rule, message } ] }
// where `path` is the field key (dotted for nested), `rule` is the failing rule
// key (e.g. "required" | "pattern" | "equals" | "custom"), `message` is human.
// `validate(value, rule)` returns the same shape with path = "" (single field).
//
// ── Sync floor + Host hook ──────────────────────────────────────────────────
// Everything here is the SYNCHRONOUS in-JS floor — runs offline, no engine.
// Server/derived validation (uniqueness, cross-record constraints) layers on top
// via `validateRecordAsync(obj, schema, host)`, which runs the sync floor first,
// then — only if a `host` with a reachable `/validate` route is given — merges
// server errors. The floor is authoritative for everything it can decide; the
// Host only ADDS errors it alone can know. Elements degrade cleanly with no host.

/** RFC-pragmatic email + url checks (deliberately permissive, not RFC-perfect). */
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const URL_RE = /^https?:\/\/[^\s.]+\.[^\s]+$/i;

function isEmpty(v) {
  return v == null || v === "" || (Array.isArray(v) && v.length === 0);
}

/** Coerce a raw value (DOM strings, etc.) by declared type for checks. */
function coerce(v, type) {
  if (v == null) return v;
  if (type === "number" || type === "integer") {
    if (typeof v === "number") return v;
    const s = String(v).trim();
    if (s === "") return NaN;
    return Number(s);
  }
  if (type === "boolean") {
    if (typeof v === "boolean") return v;
    return v === "true" || v === "on" || v === "1" || v === true;
  }
  return v;
}

function typeError(value, type) {
  switch (type) {
    case "number":
      return Number.isNaN(value) || typeof value !== "number" ? "must be a number" : null;
    case "integer":
      return Number.isNaN(value) || !Number.isInteger(value) ? "must be a whole number" : null;
    case "boolean":
      return typeof value !== "boolean" ? "must be true or false" : null;
    case "email":
      return EMAIL_RE.test(String(value)) ? null : "must be a valid email";
    case "url":
      return URL_RE.test(String(value)) ? null : "must be a valid URL";
    case "date": {
      const t = Date.parse(String(value));
      return Number.isNaN(t) ? "must be a valid date" : null;
    }
    case "string":
    default:
      return null;
  }
}

function label(rule) {
  return rule && rule.label ? rule.label : "This field";
}

/**
 * Validate ONE value against ONE rule. Synchronous, pure.
 * @param {*} value raw value
 * @param {object} rule the declarative rule
 * @param {object} [ctx] sibling values for cross-field rules ({ record, path })
 * @returns {{valid:boolean, errors:{path:string,rule:string,message:string}[]}}
 */
export function validate(value, rule, ctx = {}) {
  const errors = [];
  const path = ctx.path || "";
  const push = (rk, msg) => errors.push({ path, rule: rk, message: rule.message || msg });

  if (!rule || typeof rule !== "object") return { valid: true, errors };

  // required — short-circuits the rest if unmet (nothing else to check).
  // For a boolean field (a consent checkbox) "required" means it must be TRUE,
  // not merely present, so an unchecked box fails.
  const reqUnmet = rule.type === "boolean"
    ? coerce(value, "boolean") !== true
    : isEmpty(value);
  if (reqUnmet) {
    if (rule.required) push("required", `${label(rule)} is required.`);
    return { valid: errors.length === 0, errors };
  }

  const type = rule.type || "string";
  const v = coerce(value, type);

  // type
  const te = typeError(v, type);
  if (te) push("type", `${label(rule)} ${te}.`);

  // numeric range / length
  const isNum = type === "number" || type === "integer";
  if (rule.min != null) {
    if (isNum) { if (v < rule.min) push("min", `${label(rule)} must be at least ${rule.min}.`); }
    else { const len = String(value).length; if (len < rule.min) push("min", `${label(rule)} must be at least ${rule.min} characters.`); }
  }
  if (rule.max != null) {
    if (isNum) { if (v > rule.max) push("max", `${label(rule)} must be at most ${rule.max}.`); }
    else { const len = String(value).length; if (len > rule.max) push("max", `${label(rule)} must be at most ${rule.max} characters.`); }
  }
  if (rule.minLength != null && String(value).length < rule.minLength) push("minLength", `${label(rule)} must be at least ${rule.minLength} characters.`);
  if (rule.maxLength != null && String(value).length > rule.maxLength) push("maxLength", `${label(rule)} must be at most ${rule.maxLength} characters.`);

  // pattern
  if (rule.pattern != null) {
    const re = rule.pattern instanceof RegExp ? rule.pattern : new RegExp(rule.pattern);
    if (!re.test(String(value))) push("pattern", `${label(rule)} is not in the expected format.`);
  }

  // enum
  if (Array.isArray(rule.enum) && !rule.enum.includes(value)) {
    push("enum", `${label(rule)} must be one of: ${rule.enum.join(", ")}.`);
  }

  // cross-field equality (ctx.record carries siblings)
  if (rule.equals != null && ctx.record && ctx.record[rule.equals] !== value) {
    push("equals", `${label(rule)} must match ${rule.equals}.`);
  }

  // custom predicate — true | undefined = ok; string | false = fail (string = msg)
  if (typeof rule.custom === "function") {
    const r = rule.custom(value, ctx);
    if (r === false) push("custom", `${label(rule)} is invalid.`);
    else if (typeof r === "string") push("custom", r);
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Validate a whole record against a schema. Synchronous, pure. Every field's
 * errors carry its `path`. Sibling values are passed as ctx.record so cross-field
 * rules (equals, custom) can see the rest of the record.
 * @param {object} obj the record { path: value }
 * @param {object} schema { path: rule }
 * @returns {{valid:boolean, errors:{path:string,rule:string,message:string}[]}}
 */
export function validateRecord(obj, schema) {
  const errors = [];
  obj = obj || {};
  for (const [path, rule] of Object.entries(schema || {})) {
    const { errors: fe } = validate(obj[path], rule, { record: obj, path });
    for (const e of fe) errors.push(e);
  }
  return { valid: errors.length === 0, errors };
}

/**
 * Async record validation: the sync floor, then optional server/derived merge.
 * The floor is authoritative for everything it decides; a reachable Host only
 * ADDS errors it alone can know (uniqueness, cross-record). Degrades to the floor
 * when no host / route is reachable. Endpoint contract: POST /validate
 *   → { errors: [{path, rule, message}] }  (empty = server-clean)
 * @param {object} obj
 * @param {object} schema
 * @param {object} [host] a WbHost (this.host) — optional
 * @returns {Promise<{valid:boolean, errors:{path,rule,message}[], live:boolean}>}
 */
export async function validateRecordAsync(obj, schema, host) {
  const local = validateRecord(obj, schema);
  // Only consult the server when the floor passed (don't double-report) AND a
  // host with a /validate capability is reachable.
  if (!local.valid || !host || typeof host.available !== "function" || !host.available("validate")) {
    return { ...local, live: false };
  }
  try {
    const res = await host.request("/validate", { body: { values: obj, schema: serializeSchema(schema) } });
    const serverErrors = (res && Array.isArray(res.errors)) ? res.errors : [];
    const errors = [...local.errors, ...serverErrors];
    return { valid: errors.length === 0, errors, live: true };
  } catch {
    return { ...local, live: false };
  }
}

/**
 * Serialize a schema to JSON-safe source (RegExp → {source, flags}, functions
 * dropped — server can't run them). Lets a schema cross the Host seam / be stored
 * as composition-as-source. `parseSchema` is the inverse for the JS side.
 */
export function serializeSchema(schema) {
  const out = {};
  for (const [k, rule] of Object.entries(schema || {})) {
    const r = { ...rule };
    if (r.pattern instanceof RegExp) r.pattern = { source: r.pattern.source, flags: r.pattern.flags };
    delete r.custom; // not serializable; sync-only
    out[k] = r;
  }
  return out;
}

/** Inverse of serializeSchema for the JS floor ({source,flags} → RegExp). */
export function parseSchema(json) {
  const out = {};
  for (const [k, rule] of Object.entries(json || {})) {
    const r = { ...rule };
    if (r.pattern && typeof r.pattern === "object" && "source" in r.pattern) {
      r.pattern = new RegExp(r.pattern.source, r.pattern.flags || "");
    }
    out[k] = r;
  }
  return out;
}
